-- Explicitly drop the generated Hibernate foreign keys that were blocking deletion
ALTER TABLE student_answers DROP CONSTRAINT IF EXISTS fk8dhrgyyw99oyj0q650s1x2xo3;
ALTER TABLE student_exam_results DROP CONSTRAINT IF EXISTS fksqsdqb9r24js1ylry8bg78ybu;

-- Also drop any other FKs generated by Hibernate on these columns just in case
DO $$
DECLARE
    fk text;
BEGIN
    -- For student_answers -> questions (question_id)
    FOR fk IN (SELECT conname FROM pg_constraint WHERE conrelid = 'student_answers'::regclass AND confrelid = 'questions'::regclass AND contype = 'f' AND conname LIKE 'fk%') LOOP
        EXECUTE 'ALTER TABLE student_answers DROP CONSTRAINT IF EXISTS ' || fk;
    END LOOP;
    
    -- For student_answers -> student_exam_results (result_id)
    FOR fk IN (SELECT conname FROM pg_constraint WHERE conrelid = 'student_answers'::regclass AND confrelid = 'student_exam_results'::regclass AND contype = 'f' AND conname LIKE 'fk%') LOOP
        EXECUTE 'ALTER TABLE student_answers DROP CONSTRAINT IF EXISTS ' || fk;
    END LOOP;
END $$;

-- Add the correct ON DELETE CASCADE/SET NULL constraints again just to be safe
-- We use IF NOT EXISTS by dropping our custom ones first
ALTER TABLE student_answers DROP CONSTRAINT IF EXISTS fk_student_answers_option;
ALTER TABLE student_answers DROP CONSTRAINT IF EXISTS fk_student_answers_question;
ALTER TABLE student_answers DROP CONSTRAINT IF EXISTS fk_student_answers_result;
ALTER TABLE student_exam_results DROP CONSTRAINT IF EXISTS fk_student_exam_results_exam;

ALTER TABLE student_answers 
  ADD CONSTRAINT fk_student_answers_option FOREIGN KEY (selected_option_id) REFERENCES question_options(id) ON DELETE SET NULL,
  ADD CONSTRAINT fk_student_answers_question FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE,
  ADD CONSTRAINT fk_student_answers_result FOREIGN KEY (result_id) REFERENCES student_exam_results(id) ON DELETE CASCADE;

ALTER TABLE student_exam_results 
  ADD CONSTRAINT fk_student_exam_results_exam FOREIGN KEY (exam_id) REFERENCES exams(id) ON DELETE CASCADE;
